  "@nonagentic/n8n-nodes-scheduled-intake-actions.createKanbanCardFromIntake": {"displayName":"Create Kanban Card From Intake","properties":[{"name":"kanbanMcpUrl","displayName":"Kanban MCP URL","type":"string","description":"Base URL of the kanban-mcp service","required":true},{"name":"projectId","displayName":"Project ID","type":"string","description":"Planka project ID to create the card in","default":"","required":true},{"name":"listId","displayName":"List ID","type":"string","description":"Planka list ID to create the card in","default":"","required":true},{"name":"cardTitleField","displayName":"Card Title Field","type":"string","description":"Key from the incoming item (mapped fields) to use as the card title","default":"card_title"},{"name":"cardBodyField","displayName":"Card Body Field","type":"string","description":"Key from the incoming item to use as the card description","default":"card_body"},{"name":"cardLabelsField","displayName":"Card Labels Field","type":"string","description":"Key from the incoming item that holds an array of label names to attach. Leave blank to skip.","default":"card_labels"}],"description":"Creates a Planka kanban card via kanban-mcp using fields from a parsed IntakeEnvelope. Handles 409 duplicate responses as idempotent success (skipped=true). Wire after ParseIntakeEnvelope in a scheduled-intake workflow."},
  "@nonagentic/n8n-nodes-scheduled-intake-actions.parseIntakeEnvelope": {"displayName":"Parse Intake Envelope","properties":[{"name":"envelopeField","displayName":"Envelope Field","type":"string","description":"Field on the incoming item that contains the IntakeEnvelope JSON. Leave blank when the Webhook trigger body IS the envelope (most common).","default":""},{"name":"includeMetadata","displayName":"Include Envelope Metadata","type":"boolean","description":"Whether to include _intake_idempotency_key, _intake_source_kind, _intake_trigger_id, _intake_fetched_at, and _intake_raw_record_id fields on the output item.","default":true}],"description":"Splits an IntakeEnvelope (posted by fr-backend cron tick) into top-level n8n item fields. Use after the Webhook trigger in a scheduled-intake workflow."},
